html:
{# ═══════════════════════════════════════════════════════════════════════
   NLSAT Offer Letter — Unified Print Format
   Covers: LLB (Hons.), BA (Hons.), MPP
   DocType: Offer Letter
   ═══════════════════════════════════════════════════════════════════════ #}

{# ── 1. FETCH LINKED DOCUMENTS ── #}
{% set campus = frappe.get_doc("Campus", doc.campus) if doc.campus else None %}
{% set applicant = frappe.get_doc("Applicant", doc.applicant) if doc.applicant else None %}
{% set programme = frappe.get_doc("Programme", doc.program) if doc.program else None %}
{% set issued_date = doc.issued_on or frappe.utils.today() %}

{# ── 2. PROGRAMME IDENTIFICATION ── #}
{% set prog_level = programme.level_of_study if programme else "" %}
{% set prog_duration = programme.program_duration if programme else 3 %}
{% set pn = (doc.program or "").upper() %}

{% set is_ug = prog_level == "Undergraduate" or ("BA" in pn and "LLB" not in pn and "LL.B" not in pn) %}
{% set is_pg = not is_ug %}
{% set is_mpp = is_pg and (prog_duration == 2 or "MPP" in pn or "PUBLIC POLICY" in pn or "MASTER" in pn) %}
{% set is_llb = is_pg and not is_mpp %}
{% set is_ba = is_ug %}

{# ── 3. PROGRAMME DISPLAY NAMES ── #}
{% if is_llb %}
  {% set prog_display = "LL.B. (Hons.)" %}
  {% set fee_table_title = "Programme Fees for LLB. (Hons) Programme" %}
{% elif is_ba %}
  {% set prog_display = "BA (Hons.)" %}
  {% set fee_table_title = "Programme Fees for BA (Hons.) Programme" %}
{% elif is_mpp %}
  {% set prog_display = "Master's Programme in Public Policy" %}
  {% set fee_table_title = "Programme Fees for Master's Programme in Public Policy" %}
{% else %}
  {% set prog_display = doc.program or "Programme" %}
  {% set fee_table_title = "Programme Fees for " ~ prog_display %}
{% endif %}

{# ── 4. HOUSING TERMINOLOGY ── #}
{% set housing_option_label = "University housing" if is_ba else "Off-Campus Accommodation" %}
{% set housing_fee_label = "Housing Fee" if is_ba else "Off-Campus Housing Fee" %}
{% set housing_includes_label = "Housing Fee" if is_ba else "Off-Campus Housing Fee" %}

{# ── 5. DATES — Dynamic from system with hardcoded fallbacks ── #}
{% if doc.confirmation_fee_deadline %}
  {% set confirmation_deadline = frappe.utils.format_date(doc.confirmation_fee_deadline, "d MMMM yyyy") %}
{% else %}
  {% set confirmation_deadline = "19 June 2026" if is_llb else "25 June 2026" %}
{% endif %}

{% if doc.payment_deadline %}
  {% set full_fee_deadline = frappe.utils.format_date(doc.payment_deadline, "d MMMM yyyy") %}
{% else %}
  {% set full_fee_deadline = "24 June 2026" if is_llb else "27 June 2026" %}
{% endif %}

{# Hardcoded dates (not stored in system) #}
{% set financial_aid_deadline = "19 June 2026" if is_llb else "07 July 2026" %}
{% set registration_date = "29 June 2026" %}
{% set orientation_date = "30 June 2026" %}
{% set classes_begin_date = "1 July 2026" %}
{% set bachelors_deadline = "31 December 2026" %}
{% set full_fee_day = "24th" if is_llb else "27th" %}
{% set confirmation_day = "19th" if is_llb else "25th" %}
{% set academic_yr = doc.academic_year or "2026-2027" %}

{# ── 6. HARDCODED FEE DATA (per programme) ── #}
{% set admission_fee = "13,900" %}
{% set tuition_fee = "3,18,200" %}
{% set scst_deposit = "18,800" %}
{% set gen_deposit = "23,700" %}
{% set confirmation_fee_amt = "30,000" %}

{% if is_ba %}
  {% set housing_fee = "1,32,800" %}
  {% set total_y1 = "4,64,900" %}
  {% set total_y2 = "4,51,000" %}
  {% set total_y3 = "4,51,000" %}
  {% set total_programme = "13,66,900" %}
  {% set total_tuition_all = "9,54,600" %}
  {% set total_housing_all = "3,98,400" %}
  {% set total_scst_y1 = "4,83,700" %}
  {% set total_gen_y1 = "4,88,600" %}
{% elif is_mpp %}
  {% set housing_fee = "1,88,200" %}
  {% set total_y1 = "5,20,300" %}
  {% set total_y2 = "5,06,400" %}
  {% set total_programme = "10,26,700" %}
  {% set total_tuition_all = "6,36,400" %}
  {% set total_housing_all = "3,76,400" %}
  {% set total_scst_y1 = "5,39,100" %}
  {% set total_gen_y1 = "5,44,000" %}
{% else %}
  {# LLB default #}
  {% set housing_fee = "1,88,200" %}
  {% set total_y1 = "5,20,300" %}
  {% set total_y2 = "5,06,400" %}
  {% set total_y3 = "5,06,400" %}
  {% set total_programme = "15,51,900" %}
  {% set total_tuition_all = "9,54,600" %}
  {% set total_housing_all = "5,64,600" %}
  {% set total_scst_y1 = "5,39,100" %}
  {% set total_gen_y1 = "5,44,000" %}
{% endif %}

{% set no_housing_scst = "3,50,900" %}
{% set no_housing_gen = "3,55,800" %}

{# ── 7. UNIVERSITY INFO ── #}
{% set uni_name = campus.campus_name if campus else "National Law School of India University" %}
{% set uni_short = "NLSIU" %}
{% set uni_address = (campus.address if campus else "Nagarbhavi") ~ ", Bengaluru 560 242 (Old NO.560072)" %}
{% set uni_phone = campus.phone_number if (campus and campus.phone_number) else "080- 23010000" %}
{% set uni_email = campus.email if (campus and campus.email) else "contactus@nls.ac.in/nlsat.query@nls.ac.in" %}
{% set uni_city = campus.city if (campus and campus.city) else "Bengaluru" %}

{# ══════════════════════════════════════════════════════════════════════ #}
{# CSS STYLES                                                           #}
{# ══════════════════════════════════════════════════════════════════════ #}
<style>
@page { size: A4; margin: 15mm 18mm 20mm 18mm; }

/* ---------- Global ---------- */
.nlsat-offer { font-family: 'Times New Roman', Georgia, serif; color: #1a1a1a; font-size: 11pt; line-height: 1.55; }
.nlsat-offer * { box-sizing: border-box; }

/* ---------- Page break ---------- */
.page-break { page-break-before: always; }

/* ---------- Letterhead ---------- */
.lh { text-align: center; padding-bottom: 8px; margin-bottom: 16px; }
.lh-name { font-size: 14pt; font-weight: 700; text-transform: uppercase; letter-spacing: 0.03em; margin: 0 0 2px; }
.lh-addr { font-size: 9.5pt; color: #333; margin: 0; }
.lh-phone { font-size: 9.5pt; color: #333; margin: 0; }
.lh-email { font-size: 9.5pt; color: #333; margin: 0 0 4px; }

/* ---------- Body text ---------- */
.para { text-align: justify; margin-bottom: 10px; }
.bold { font-weight: 700; }
.indent { margin-left: 28px; }

/* ---------- Appendix titles ---------- */
.app-title { text-align: center; font-size: 12pt; font-weight: 700; margin: 12px 0 4px; }
.app-subtitle { text-align: center; font-size: 11pt; font-weight: 700; margin: 0 0 16px; }

/* ---------- Ordered/unordered lists ---------- */
.step-list { padding-left: 26px; margin: 10px 0; }
.step-list li { margin-bottom: 8px; text-align: justify; }
.sub-list { list-style-type: lower-alpha; margin: 6px 0 6px 20px; padding-left: 0; }
.sub-list li { margin-bottom: 4px; }
.note-text { font-size: 10pt; margin-top: 6px; font-style: italic; color: #333; }

/* ---------- Fee table ---------- */
.fee-table { width: 100%; border-collapse: collapse; font-size: 10pt; margin: 12px 0; }
.fee-table th, .fee-table td { border: 1px solid #666; padding: 6px 8px; text-align: center; vertical-align: middle; }
.fee-table th { background: #f5f5f5; font-weight: 700; }
.fee-table td:first-child { text-align: left; }
.fee-note { font-size: 10pt; margin: 8px 0; }
.fee-note ul { padding-left: 20px; margin: 6px 0; }
.fee-note li { margin-bottom: 6px; }

/* ---------- Deadline table ---------- */
.deadline-table { width: 100%; border-collapse: collapse; font-size: 10pt; margin: 12px 0; }
.deadline-table th, .deadline-table td { border: 1px solid #666; padding: 6px 8px; vertical-align: top; }
.deadline-table th { background: #f5f5f5; font-weight: 700; }

/* ---------- FAQ ---------- */
.faq-section-title { font-weight: 700; font-size: 11pt; margin: 14px 0 6px; }
.faq-q { font-weight: 700; margin: 10px 0 2px; text-indent: 20px; }
.faq-a { margin: 0 0 8px 0; text-align: justify; }

/* ---------- Signature ---------- */
.sig { margin-top: 32px; }
.sig-name { font-weight: 700; margin: 0 0 2px; }
.sig-desg { margin: 0; }

/* ---------- Footer ---------- */
.pg-footer { margin-top: 24px; padding-top: 8px; border-top: 1px solid #999; font-size: 8pt; color: #666; text-align: center; }
</style>

<div class="nlsat-offer">

{# ══════════════════════════════════════════════════════════════════════ #}
{# COVER LETTER (PAGE 1)                                                #}
{# ══════════════════════════════════════════════════════════════════════ #}
<div class="cover-page">
  <div class="lh">
    {% if campus and campus.logo %}
      <img src="{{ campus.logo }}" alt="Logo" style="max-width:80px; max-height:75px; margin-bottom:6px;">
    {% endif %}
    <p class="lh-name">{{ uni_name }}</p>
    <p class="lh-addr">{{ uni_address }}</p>
    <p class="lh-phone">Phone: {{ uni_phone }}</p>
    <p class="lh-email">Email: {{ uni_email }}</p>
  </div>

  <p><strong>Date:</strong> {{ frappe.utils.format_date(issued_date, "d MMMM yyyy") }}</p>
  <p><strong>Dear {{ applicant.candidate_name if applicant else "Candidate" }},</strong></p>
  <p style="font-weight:700; font-size:12pt;">Congratulations!</p>

  <p class="para">
    We are glad to provisionally offer you admission to the <strong>{{ doc.program }}</strong> programme at the
    {{ uni_name }}. We look forward to welcoming you to {{ uni_short }}.
  </p>

  <p class="para">
    Please log in to the Admissions Portal (https://nlsatadmissions.nls.ac.in/) to accept the
    provisional offer of admission and complete the next steps online as indicated below:
  </p>

  <ol class="step-list">
    <li>In order to confirm this provisional offer, you must pay <strong>Rs. {{ confirmation_fee_amt }}</strong> as a confirmation fee. The full fees applicable to the individual candidate for the academic year {{ academic_yr }} will have to be paid by <strong>{{ full_fee_deadline }}</strong>. More information about how to accept this provisional offer is available in the email sent to you with the provisional offer of admission.</li>
    <li>This offer is contingent upon the verification of particulars furnished in the application form. In the next few days, you may receive an email from the {{ uni_short }} admissions team if there are queries on the information and documents submitted along with your application. Submitting incomplete, invalid, or false information/documents shall result in the withdrawal of the provisional offer of admission.</li>
    <li>You are required to be present at the {{ uni_short }} campus in {{ uni_city }}, on <strong>{{ registration_date }}</strong> onwards for registration and onboarding. The orientation programme will commence on the date as communicated to you. The schedule for the orientation will be announced later.</li>
    <li>On the date of registration, the University will conduct an in-person verification of the original certificates you have submitted via the admissions portal. Your provisional admission will be confirmed only after successful verification of the following original documents and full payment of the fees:
      <ul class="sub-list">
        <li>Class 10 transcript</li>
        <li>Class 12 transcript</li>
        {% if is_pg %}<li>Bachelor's degree certificate and transcript*</li>{% endif %}
        <li>Caste certificate, if applicable</li>
        <li>EWS certificate, if applicable</li>
        <li>Disability certificate, if applicable</li>
        <li>Documents relating to qualifying for Karnataka category, if applicable</li>
      </ul>
      <div class="note-text">
        {% if is_pg %}
        * Candidates who are yet to receive the certificate/transcripts of their Bachelor's degree shall submit a declaration to the effect that the certificate/transcripts shall be submitted on or before {{ bachelors_deadline }}. Their admission will remain provisional until the degree certificate and final marks transcript, indicating that the candidate has met the eligibility criteria, is submitted.
        {% else %}
        * Candidates who are yet to receive the certificate/transcripts of their Class XII examination shall submit a declaration to the effect that the certificate/transcripts shall be submitted on or before {{ bachelors_deadline }}. Their admission will remain provisional until the certificate and final marks transcript, indicating that the candidate has met the eligibility criteria, is submitted.
        {% endif %}
      </div>
    </li>
    <li>Failure to submit any of the above valid certificates at the time of verification shall result in the withdrawal of the provisional offer of admission.</li>
    <li>You are also required to submit two passport-size colour photographs to the Admissions Office at the time of the verification.</li>
    <li>The University will send you additional documents. Please upload scans of the signed copies as per the instructions, which will follow along with the documents. On the date of verification of documents, you will be required to carry originals of these documents:
      <ul class="sub-list">
        <li>Email Receipt of Submission of the Online Anti-Ragging Undertaking Required by the UGC</li>
        <li>Disciplinary Undertaking</li>
        <li>{% if is_ba %}Housing Application Form{% else %}Off-Campus Housing Application Form{% endif %}</li>
        <li>Residential Students' Declaration Form</li>
      </ul>
    </li>
    <li>{% if is_ba %}All students of the {{ prog_display }} programme are eligible to apply for University housing. Further details about accommodation are available in the email sent to you with the provisional offer of admission.{% else %}All students of the {{ prog_display }} programme shall be provided with off-campus accommodation. Further details about accommodation are available in the email sent to you with the provisional offer of admission.{% endif %}</li>
    <li>The University will organise a welcome and orientation programme for all candidates. A detailed schedule regarding the same will be provided in the latter half of June.</li>
  </ol>

  <div class="sig">
    <p class="sig-name">Registrar</p>
    <p class="sig-desg">{{ uni_name }}</p>
  </div>

  <div class="pg-footer">
    A University for Legal Studies and Research sponsored by the Bar Council of India and established under Karnataka Act 22 of 1986
  </div>
</div>

{# ══════════════════════════════════════════════════════════════════════ #}
{# APPENDIX I — Steps to Accept the Provisional Offer                  #}
{# ══════════════════════════════════════════════════════════════════════ #}
<div class="page-break">
  <div class="lh">
    <p class="lh-name">{{ uni_name }}</p>
    <p class="lh-addr">{{ uni_address }}</p>
    <p class="lh-phone">Phone: {{ uni_phone }}</p>
    <p class="lh-email">Email: {{ uni_email }}</p>
  </div>

  <p class="app-title">Appendix I:</p>
  <p class="app-subtitle">Steps to Accept the Provisional Offer of Admission</p>

  <ol class="step-list">
    <li>Login into the Admission Portal.</li>
    <li>Click on the button "Accept Offer of Admission."</li>
    <li>On the next page, you will have an option of selecting whether you would like to apply for "{{ housing_option_label }}". If you select "Yes", then the housing fees will be added to your fees. If you do not want {% if is_ba %}university housing{% else %}"off campus accommodation"{% endif %}, you may select "no"</li>
    <li>Click the "Make Payment" button, to pay an admission confirmation fee of Rs. {{ confirmation_fee_amt }} only. Follow the instructions to make the payment. You need to make the confirmation payment latest by 11:59 PM on {{ confirmation_deadline }}.</li>
    <li>On submission of your form, the University will generate a fee invoice for the balance amount, and you will be notified of the same via email.</li>
    <li>Log back into the portal and click on the "Make Payment" button to pay the balance fee amount. Make the complete payment latest by 11:59 pm on {{ full_fee_deadline }}.</li>
    <li>Once the full fee is paid, NLSIU will send you a form to gather necessary information and upload additional documents.</li>
    <li>You will need to bring your original documents to NLSIU campus during your allotted registration slot on {{ registration_date }}. You will be registered as a student after verification of all documents, admission forms and fee payment.</li>
    <li>Your admission will become final only upon successful completion of all the steps above.</li>
    <li>If you choose not to accept the seat you have been offered, please email nlsat.query@nls.ac.in from your registered address with your full name, NLSAT application number, the programme offered and a clear statement that you wish to withdraw your application. The date we receive your email will count for any refund calculations. Once processed, the withdrawal is final.</li>
  </ol>

  <p class="para">
    The FAQ below answers some of the most common questions about the admission process. Any
    further queries relating to the admission process may be sent to nlsat.query@nls.ac.in with the
    following subject line: "NLSAT Admission Query – [insert admit card number]".
  </p>

  <div class="pg-footer">
    A University for Legal Studies and Research sponsored by the Bar Council of India and established under Karnataka Act 22 of 1986
  </div>
</div>

{# ══════════════════════════════════════════════════════════════════════ #}
{# APPENDIX II — Programme Fees                                        #}
{# ══════════════════════════════════════════════════════════════════════ #}
<div class="page-break">
  <div class="lh">
    <p class="lh-name">{{ uni_name }}</p>
    <p class="lh-addr">{{ uni_address }}</p>
    <p class="lh-phone">Phone: {{ uni_phone }}</p>
    <p class="lh-email">Email: {{ uni_email }}</p>
  </div>

  <p class="app-title">Appendix II:</p>
  <p class="app-subtitle">{{ fee_table_title }}</p>

  <table class="fee-table">
    <thead>
      <tr>
        <th style="width:30%;">Fee Component</th>
        <th>Year 1</th>
        <th>Year 2</th>
        {% if prog_duration >= 3 %}<th>Year 3</th>{% endif %}
        <th>Total Programme Fees</th>
      </tr>
    </thead>
    <tbody>
      <tr>
        <td>Admission Fee (One-time)</td>
        <td>Rs. {{ admission_fee }}/-</td>
        <td>—</td>
        {% if prog_duration >= 3 %}<td>—</td>{% endif %}
        <td>Rs. {{ admission_fee }}/-</td>
      </tr>
      <tr>
        <td>Tuition &amp; Facilities Fee (Annual)</td>
        <td>Rs. {{ tuition_fee }}/-</td>
        <td>Rs. {{ tuition_fee }}/-</td>
        {% if prog_duration >= 3 %}<td>Rs. {{ tuition_fee }}/-</td>{% endif %}
        <td>Rs. {{ total_tuition_all }}/-</td>
      </tr>
      <tr>
        <td>{{ housing_fee_label }} (Annual, includes meals)</td>
        <td>Rs. {{ housing_fee }}/-</td>
        <td>Rs. {{ housing_fee }}/-</td>
        {% if prog_duration >= 3 %}<td>Rs. {{ housing_fee }}/-</td>{% endif %}
        <td>Rs. {{ total_housing_all }}/-</td>
      </tr>
      <tr style="font-weight:700;">
        <td>Total Cost to Student</td>
        <td>Rs. {{ total_y1 }}/-</td>
        <td>Rs. {{ total_y2 }}/-</td>
        {% if prog_duration >= 3 %}<td>Rs. {{ total_y3 }}/-</td>{% endif %}
        <td>Rs. {{ total_programme }}/-</td>
      </tr>
    </tbody>
  </table>

  <table class="fee-table" style="margin-top:12px;">
    <thead>
      <tr>
        <th style="width:30%;">Deposits</th>
        <th>Year 1</th>
        <th>Year 2</th>
        {% if prog_duration >= 3 %}<th>Year 3</th>{% endif %}
        <th></th>
      </tr>
    </thead>
    <tbody>
      <tr>
        <td>Refundable Deposit (One-time) for SC/ST Students</td>
        <td>Rs. {{ scst_deposit }}/-</td>
        <td>—</td>
        {% if prog_duration >= 3 %}<td>—</td>{% endif %}
        <td>—</td>
      </tr>
      <tr>
        <td>Refundable Deposit (One-time) for General and Other Categ</td>
        <td>Rs. {{ gen_deposit }}/-</td>
        <td>—</td>
        {% if prog_duration >= 3 %}<td>—</td>{% endif %}
        <td>—</td>
      </tr>
    </tbody>
  </table>

  <div class="fee-note">
    <p><strong>Note:</strong></p>
    <ul>
      <li>A 'one-time admission fee' of Rs {{ admission_fee }} will be collected at the time of admission.</li>
      {% if is_mpp %}
      <li>{{ housing_fee_label }} will only be collected for candidates who apply for university housing.</li>
      {% endif %}
      <li>A refundable security deposit of Rs. {{ scst_deposit }} for SC/ST category students and Rs. {{ gen_deposit }} for other students will be collected at the time of admission. The security deposit will be refunded upon graduation or withdrawal from the programme, subject to deductions towards applicable convocation fees, certificate issuance fees, and any outstanding dues.</li>
      <li>The {{ housing_includes_label }} includes a meal plan covering breakfast, lunch, dinner and an evening snack.</li>
    </ul>
  </div>

  <p class="para" style="margin-top:12px;">
    {% if is_mpp %}
    The total fees payable (including deposits) for students who opt for accommodation by students for the first year before {{ full_fee_deadline }} in the SC/ST category is <strong>Rs. {{ total_scst_y1 }}</strong> and by students in the general and other categories is <strong>Rs. {{ total_gen_y1 }}</strong>.
    {% else %}
    The total fees payable by students for the first year before {{ full_fee_deadline }} in the SC/ST category is <strong>Rs. {{ total_scst_y1 }}</strong> and by students in the general and other categories is <strong>Rs. {{ total_gen_y1 }}</strong>.
    {% endif %}
  </p>

  <div class="pg-footer">
    A University for Legal Studies and Research sponsored by the Bar Council of India and established under Karnataka Act 22 of 1986
  </div>
</div>

{# ══════════════════════════════════════════════════════════════════════ #}
{# APPENDIX III — Financial Aid and Scholarships                       #}
{# ══════════════════════════════════════════════════════════════════════ #}
<div class="page-break">
  <div class="lh">
    <p class="lh-name">{{ uni_name }}</p>
    <p class="lh-addr">{{ uni_address }}</p>
    <p class="lh-phone">Phone: {{ uni_phone }}</p>
    <p class="lh-email">Email: {{ uni_email }}</p>
  </div>

  <p class="app-title">Appendix III</p>
  <p class="app-subtitle">Financial Aid and Scholarships</p>

  <p class="para">Students are admitted to NLSIU based on their academic performance in the admission process. The University has adopted an inclusion policy that ensures that students from diverse social, linguistic and economic backgrounds from across India benefit from a rigorous and transformative education. The admission process does not take into account the financial background of the applicant. Student fees for on-campus academic programmes cover only part of the actual cost of education, with the University subsidising the remaining cost. Further, the University is dedicated to ensuring that students admitted to an academic programme are provided with necessary support to continue their studies, irrespective of financial constraints. The Financial Aid Policy sets out the University's approach to delivering on this commitment.</p>

  <p class="para">Students whose gross family income is less than Rs. 8,00,000 per annum are eligible to apply for financial aid by the university. Before submitting their application for University's financial aid, candidates must apply under the PM Vidyalaxmi Scheme. NLSIU has been recognised by the Government of India under the PM-Vidyalaxmi Scheme as one of the leading higher educational institutions in the country. The PM Vidyalaxmi Scheme provides collateral-free and guarantor-free education loans to meritorious students in top institutions in India. There is no income limit to apply for this scheme, and loans up to Rs. 30 lakhs can be availed. Partial and full interest subvention is available for lower annual family incomes.</p>

  <p class="para">The application to PM Vidyalaxmi Scheme must be filled through the official PM Vidyalaxmi Portal: https://pmvidyalaxmi.co.in before applying for financial aid with the University. For detailed guidelines &amp; process, please visit PM Vidyalaxmi Scheme section of the universities scholarship page. A copy of the education loan application must be submitted along with the application for university financial aid. This is a pre-condition for applying for financial aid through the University. In the absence of this document, the financial aid process will be kept in abeyance.</p>

  <p class="para">Candidates who wish to apply for financial assistance under the University's Financial Aid Policy are required to submit their application for financial aid on or before <strong>{{ financial_aid_deadline }}, 11.59 p.m.</strong> The University will communicate its decision on the financial aid applications by 31 July 2026. Students who are provided financial aid shall have their fee reimbursed up to the extent of the aid provided. Application for financial aid does not exempt you from payment of the full fees before {{ full_fee_deadline }}.</p>

  <p class="para">Students who have been admitted to NLSIU may also be eligible for a number of scholarships sponsored by the central and state governments as well as private organisations. NLSIU has curated a list of some such scholarships for the benefit of candidates. Students may also visit the National Scholarship Portal for more information. For further assistance in this regard, please contact nlsiuscholarship@nls.ac.in.</p>

  <div class="pg-footer">
    A University for Legal Studies and Research sponsored by the Bar Council of India and established under Karnataka Act 22 of 1986
  </div>
</div>

